    <section className='container-fluid px-0 min-vh-100 d-flex justify-content-center align-items-center bg-gradient-black'>
      <article>
      <img src={home.image.url} alt={home.image.alt} width={home.image.width}  className='avatar'/>
          <h2>Old Mate<br/>Cranes & Rigging</h2>
          <h1>{home.title}</h1>
          <p>Hello there. How do you do?</p>

      </article>
    </section>
    </section>
    </>
  );
}
